-- What 0.9.13 stored for files sent through a chat app the adapter host ran, written by v0.9.13's own
-- GatewayStateRepository.upsert_attachment and ConversationRepository; tests/test_adapter_host_files_upgrade.py.
-- Paths use the placeholder instance root /instance.
-- database: gateway
CREATE TABLE gateway_attachments ( attachment_id TEXT PRIMARY KEY, session_key TEXT NOT NULL, conversation_id TEXT, correlation_id TEXT, owner_canonical_user_id TEXT, filename TEXT NOT NULL, content_type TEXT NOT NULL, kind TEXT NOT NULL, size_bytes INTEGER NOT NULL, sha256 TEXT NOT NULL, local_path TEXT NOT NULL, nats_bucket TEXT, nats_object_name TEXT, created_at TEXT NOT NULL, expires_at TEXT );
CREATE INDEX idx_gateway_attachments_created ON gateway_attachments(created_at);
CREATE INDEX idx_gateway_attachments_session ON gateway_attachments(session_key, created_at DESC);
